// Long value tag bits:
// 0-1: Sign bits value = (1-sign), ie. negative=2, positive=0, zero=1.
// 2: Set to 1 for the small ints
// 3+ Unsigned digit count
fn _PyLong_IsNegative(op: *const _longobject) -> bool {
    (unsafe { (*op).long_value.lv_tag }) & 3 == 2
}

