// _PyOS_URandom()
// _PyInterpreterState_GET()
// Py_NSIG
// _PyLong_FromTime_t()
// _PyType_AddMethod()
// _PyLong_FromUid()
// --- System includes ------------------------------------------------------
// ctermid()
// system()
// symlink()
// futimes()
// PIDFD_NONBLOCK
// Should be included before <sys/sysmacros.h> on HP-UX v3
// GNU C Library: major(), minor(), makedev()
// WNOHANG
// P_PIDFD
// fcntl()
// setgroups()
// EX_OK
// sendfile()
// sched_setscheduler()
// SCHED_IDLE, SCHED_RR
// GRND_RANDOM
// syscall()
// posix_spawn()
// utime()
// times()
// uname()
// memfd_create is either defined in sys/mman.h or sys/memfd.h
// linux/memfd.h defines additional flags
// memfd_create()
// memfd_create(), MFD_CLOEXEC
// eventfd()
// timerfd_create()
